#define SCL_PIN 4
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

#define BTN_UP     9
#define BTN_DOWN   12
#define BTN_LEFT   13
#define BTN_RIGHT  10
#define BTN_OK     14

// ============================================================
// GAME CENTER - فقط انتخاب بازی؛ گیم‌پلی دو بازی دست‌نخورده است
// ============================================================
enum GameMode { GAME_SELECTOR, GAME_SNAKE, GAME_PACMAN };
GameMode gameMode = GAME_SELECTOR;
int selectedGame = 0;
bool selectorLastUp = HIGH;
bool selectorLastDown = HIGH;
bool selectorLastOK = HIGH;

bool leftWasDown = false;
bool waitingSecondLeft = false;
unsigned long firstLeftTime = 0;
const unsigned long DOUBLE_LEFT_TIME = 550;

bool pressedOnce(int pin, bool &lastState) {
  bool now = digitalRead(pin);
  bool pressed = (now == LOW && lastState == HIGH);
  lastState = now;
  return pressed;
}

bool checkDoubleLeftExit() {
  bool nowDown = (digitalRead(BTN_LEFT) == LOW);
  bool pressed = nowDown && !leftWasDown;
  leftWasDown = nowDown;

  if (pressed) {
    unsigned long now = millis();
    if (waitingSecondLeft && now - firstLeftTime <= DOUBLE_LEFT_TIME) {
      waitingSecondLeft = false;
      return true;
    }
    waitingSecondLeft = true;
    firstLeftTime = now;
  }

  if (waitingSecondLeft && millis() - firstLeftTime > DOUBLE_LEFT_TIME) {
    waitingSecondLeft = false;
  }
  return false;
}

void showGameSelector() {
  display.clearDisplay();
  display.setTextColor(SSD1306_WHITE);

  display.setTextSize(1);
  display.setCursor(38, 4);
  display.print("SELECT GAME");

  display.setCursor(34, 25);
  display.print(selectedGame == 0 ? "> Snake" : "  Snake");

  display.setCursor(30, 45);
  display.print(selectedGame == 1 ? "> Pac-Man" : "  Pac-Man");

  display.display();
}

void enterSelectedGame() {
  waitingSecondLeft = false;
  leftWasDown = (digitalRead(BTN_LEFT) == LOW);

  if (selectedGame == 0) {
    gameMode = GAME_SNAKE;
    s_inMenu = true;
    s_inDiffMenu = false;
  } else {
    gameMode = GAME_PACMAN;
    p_inMenu = true;
    p_inDiffMenu = false;
  }
}

void exitToGameSelector() {
  gameMode = GAME_SELECTOR;
  selectedGame = (gameMode == GAME_SELECTOR && selectedGame < 2) ? selectedGame : 0;
  waitingSecondLeft = false;
  leftWasDown = (digitalRead(BTN_LEFT) == LOW);
  display.clearDisplay();
  display.display();
}

void setup() {
  Wire.begin(SDA_PIN, SCL_PIN);
  delay(100);

  if (!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    if (!display.begin(SSD1306_SWITCHCAPVCC, 0x3D)) for(;;);
  }

  pinMode(BTN_UP, INPUT_PULLUP);
  pinMode(BTN_DOWN, INPUT_PULLUP);
  pinMode(BTN_LEFT, INPUT_PULLUP);
  pinMode(BTN_RIGHT, INPUT_PULLUP);
  pinMode(BTN_OK, INPUT_PULLUP);

  EEPROM.begin(16);
  snake_setup();
  pac_setup();

  display.clearDisplay();
  display.display();
}

void loop() {
  if (gameMode == GAME_SELECTOR) {
    if (pressedOnce(BTN_UP, selectorLastUp)) selectedGame = 0;
    if (pressedOnce(BTN_DOWN, selectorLastDown)) selectedGame = 1;
    if (pressedOnce(BTN_OK, selectorLastOK)) enterSelectedGame();
    showGameSelector();
    return;
  }

  // دو بار LEFT در هر حالت بازی = خروج به انتخاب بازی
  if (checkDoubleLeftExit()) {
    exitToGameSelector();
    return;
  }

  if (gameMode == GAME_SNAKE) {
    snake_loop();
  } else if (gameMode == GAME_PACMAN) {
    pac_loop();
  }
}

