void snake_setSpeedByDiff() {
  if (s_currentDiff == 0) s_speed = 280;
  else if (s_currentDiff == 1) s_speed = 180;
  else s_speed = 110;
}

bool snake_isOnSnake(int x, int y) {
  for (int i = 0; i < s_snakeLength; i++) {
    if (s_snakeX[i] == x && s_snakeY[i] == y) return true;
  }
  return false;
}

void snake_placeFood() {
  int tries = 0;
  do {
    s_foodX = random(1, (SCREEN_WIDTH / S_GRID_SIZE) - 1) * S_GRID_SIZE;
    s_foodY = random(3, (SCREEN_HEIGHT / S_GRID_SIZE) - 1) * S_GRID_SIZE;
    tries++;
  } while (snake_isOnSnake(s_foodX, s_foodY) && tries < 100);
}

void snake_resetGame() {
  s_snakeLength = 3;
  s_snakeX[0] = 16; s_snakeY[0] = 16;
  s_snakeX[1] = 12; s_snakeY[1] = 16;
  s_snakeX[2] = 8;  s_snakeY[2] = 16;
  s_dir = 1;
  s_score = 0;
  s_gameOver = false;
  s_isPaused = false;
  s_isNewRecord = false;
  s_showR = false;
  s_deathAnimDone = false;
  s_okPressCount = 0;
  snake_setSpeedByDiff();
  snake_placeFood();
}

void snake_saveHighScore() {
  bool newRecord = false;
  if (s_currentDiff == 0 && s_score > s_highScoreEasy) {
    s_highScoreEasy = s_score;
    EEPROM.write(S_EEPROM_HS_EASY, s_highScoreEasy);
    newRecord = true;
  }
  else if (s_currentDiff == 1 && s_score > s_highScoreNormal) {
    s_highScoreNormal = s_score;
    EEPROM.write(S_EEPROM_HS_NORMAL, s_highScoreNormal);
    newRecord = true;
  }
  else if (s_currentDiff == 2 && s_score > s_highScoreHard) {
    s_highScoreHard = s_score;
    EEPROM.write(S_EEPROM_HS_HARD, s_highScoreHard);
    newRecord = true;
  }

  if (newRecord) {
    EEPROM.commit();
    s_isNewRecord = true;
    // فقط یک بار R رو نشون بده
    if (!s_showR) {
      s_showR = true;
      s_rTimer = millis();
    }
  }
}

int snake_getCurrentHighScore() {
  if (s_currentDiff == 0) return s_highScoreEasy;
  if (s_currentDiff == 1) return s_highScoreNormal;
  return s_highScoreHard;
}

void snake_drawSkull(int x, int y) {
  display.fillCircle(x + 6, y + 5, 6, SSD1306_WHITE);
  display.fillRect(x + 3, y + 8, 7, 5, SSD1306_WHITE);
  display.fillRect(x + 4, y + 4, 2, 2, SSD1306_BLACK);
  display.fillRect(x + 9, y + 4, 2, 2, SSD1306_BLACK);
  display.drawLine(x + 6, y + 10, x + 6, y + 12, SSD1306_BLACK);
}

void snake_drawStar(int x, int y) {
  // ستاره ساده‌تر و قشنگ‌تر
  display.drawLine(x, y-4, x, y+4, SSD1306_WHITE);
  display.drawLine(x-4, y, x+4, y, SSD1306_WHITE);
  display.drawLine(x-3, y-3, x+3, y+3, SSD1306_WHITE);
  display.drawLine(x-3, y+3, x+3, y-3, SSD1306_WHITE);
  display.fillCircle(x, y, 1, SSD1306_WHITE);
}


void snake_setup() {
  s_currentDiff = EEPROM.read(S_EEPROM_DIFF);
  if (s_currentDiff > 2) s_currentDiff = 1;
  s_diffIndex = s_currentDiff;

  s_highScoreEasy = EEPROM.read(S_EEPROM_HS_EASY);
