  if (s_highScoreEasy > 200) s_highScoreEasy = 0;
  if (s_highScoreNormal > 200) s_highScoreNormal = 0;
  if (s_highScoreHard > 200) s_highScoreHard = 0;
  s_inMenu = true;
  s_inDiffMenu = false;
}

