void pac_moveGhost() {
  int tries = 0;
  while (tries < 10) {
    int gdir = random(0, 4);
    int nx = p_ghostX, ny = p_ghostY;
    if (gdir == 0) ny--;
    if (gdir == 1) nx++;
    if (gdir == 2) ny++;
    if (gdir == 3) nx--;
    if (pac_canMove(nx, ny)) {
      p_ghostX = nx; p_ghostY = ny;
      break;
    }
    tries++;
  }
}

