void snake_loop() {
  // ========== منوی اصلی ==========
  if (s_inMenu) {
    if (millis() - s_animTimer > 280) {
      s_animTimer = millis();
      s_animOffset += s_animDir ? 1 : -1;
      if (s_animOffset > 3) s_animDir = false;
      if (s_animOffset < -3) s_animDir = true;
    }

    if (digitalRead(BTN_UP) == LOW) { s_menuIndex = 0; delay(200); }
    if (digitalRead(BTN_DOWN) == LOW) { s_menuIndex = 1; delay(200); }
    if (digitalRead(BTN_OK) == LOW) {
      delay(250);
      if (s_menuIndex == 0) {
        s_inMenu = false;
        snake_resetGame();
      } else {
        s_inMenu = false;
        s_inDiffMenu = true;
      }
    }

    display.clearDisplay();
    display.setTextSize(2);
    display.setTextColor(SSD1306_WHITE);
    display.setCursor(22 + s_animOffset, 9);
    display.print("KomiXer");

    display.setTextSize(1);
    display.setCursor(35, 32);
    if (s_menuIndex == 0) display.print("> Start");
    else display.print("  Start");

    display.setCursor(18, 48);
    if (s_menuIndex == 1) display.print("> Select Difficulty");
    else display.print("  Select Difficulty");

    display.display();
    return;
  }

  // ========== منوی سختی ==========
  if (s_inDiffMenu) {
    if (digitalRead(BTN_UP) == LOW) { if (s_diffIndex > 0) s_diffIndex--; delay(200); }
    if (digitalRead(BTN_DOWN) == LOW) { if (s_diffIndex < 2) s_diffIndex++; delay(200); }
    if (digitalRead(BTN_OK) == LOW) {
      delay(250);
      s_currentDiff = s_diffIndex;
      EEPROM.write(S_EEPROM_DIFF, s_currentDiff);
      EEPROM.commit();
      s_inDiffMenu = false;
      s_inMenu = true;
    }

    display.clearDisplay();
    display.setTextSize(1);
    display.setCursor(30, 6);
    display.print("Difficulty");

    display.setCursor(40, 24);
    if (s_diffIndex == 0) display.print("> Easy");
    else display.print("  Easy");

    display.setCursor(35, 38);
    if (s_diffIndex == 1) display.print("> Normal");
    else display.print("  Normal");

    display.setCursor(40, 52);
    if (s_diffIndex == 2) display.print("> Hard");
    else display.print("  Hard");

    display.display();
    return;
  }

  // ========== Pause / Unpause ==========
  if (!s_gameOver && digitalRead(BTN_OK) == LOW) {
    delay(180);

    if (s_isPaused) {
      s_isPaused = false;
      s_okPressCount = 0;
    } else {
      if (millis() - s_lastOkPress < 500) {
        s_okPressCount++;
      } else {
        s_okPressCount = 1;
      }
      s_lastOkPress = millis();

      if (s_okPressCount >= 2) {
        s_isPaused = true;
        s_okPressCount = 0;
      }
    }
  }

  if (s_isPaused && digitalRead(BTN_DOWN) == LOW) {
    delay(250);
    s_isPaused = false;
    s_inMenu = true;
  }

  if (s_isPaused) {
    display.clearDisplay();
    display.setTextSize(2);
    display.setCursor(28, 18);
    display.print("PAUSE!");

    display.setTextSize(1);
    display.setCursor(22, 48);
    display.print("DOWN = Menu");

    display.display();
    return;
  }

  // ========== Game Over (دو مرحله‌ای) ==========
  if (s_gameOver) {
    // مرحله ۱: چشمک‌زن + اسکلت (حدود ۲ ثانیه)
    if (!s_deathAnimDone) {
      if (millis() - s_deathStart > 2000) {
        s_deathAnimDone = true;
        s_animTimer = millis();
      }

      if (millis() - s_animTimer > 350) {
        s_animTimer = millis();
        s_animOffset = (s_animOffset == 0) ? 1 : 0;
      }

      display.clearDisplay();

      if (s_animOffset == 0) {
        display.setTextSize(2);
        display.setCursor(12, 8);
        display.print("Game Over");
      }

      snake_drawSkull(52, 30);   // اسکلت فقط تو این مرحله

      display.display();
      return;
    }

    // مرحله ۲: Game Over متحرک چپ و راست
    if (millis() - s_animTimer > 350) {
      s_animTimer = millis();
      s_animOffset = (s_animOffset == 0) ? 2 : 0;
    }

    display.clearDisplay();

    display.setTextSize(2);
    display.setCursor(12 + s_animOffset, 12);   // کمی پایین‌تر
    display.print("Game Over");

    display.setTextSize(1);
    display.setCursor(30, 36);
    display.print("Score: ");
    display.print(s_score);

    display.setCursor(8, 50);
    if (s_currentDiff == 0) display.print("Easy Best: ");
    else if (s_currentDiff == 1) display.print("Normal Best: ");
    else display.print("Hard Best: ");
    display.print(snake_getCurrentHighScore());

    // ستاره پایین‌تر و قشنگ‌تر
    if (s_isNewRecord) {
      snake_drawStar(110, 40);
    }

    display.display();

    if (digitalRead(BTN_OK) == LOW) {
      delay(300);
      s_inMenu = true;
    }
    return;
  }

  // ========== کنترل جهت ==========
  if (digitalRead(BTN_UP) == LOW && s_dir != 2) { s_dir = 0; delay(130); }
  if (digitalRead(BTN_DOWN) == LOW && s_dir != 0) { s_dir = 2; delay(130); }
  if (digitalRead(BTN_LEFT) == LOW && s_dir != 1) { s_dir = 3; delay(130); }
  if (digitalRead(BTN_RIGHT) == LOW && s_dir != 3) { s_dir = 1; delay(130); }

  // ========== حرکت مار ==========
  if (millis() - s_lastMove > s_speed) {
    s_lastMove = millis();

    for (int i = s_snakeLength - 1; i > 0; i--) {
      s_snakeX[i] = s_snakeX[i - 1];
      s_snakeY[i] = s_snakeY[i - 1];
    }

    if (s_dir == 0) s_snakeY[0] -= S_GRID_SIZE;
    if (s_dir == 1) s_snakeX[0] += S_GRID_SIZE;
    if (s_dir == 2) s_snakeY[0] += S_GRID_SIZE;
    if (s_dir == 3) s_snakeX[0] -= S_GRID_SIZE;

    if (s_snakeX[0] < 0 || s_snakeX[0] >= SCREEN_WIDTH || s_snakeY[0] < 8 || s_snakeY[0] >= SCREEN_HEIGHT) {
      s_gameOver = true;
      s_deathStart = millis();
      s_animTimer = millis();
      s_deathAnimDone = false;
      snake_saveHighScore();
    }

    for (int i = 1; i < s_snakeLength; i++) {
      if (s_snakeX[0] == s_snakeX[i] && s_snakeY[0] == s_snakeY[i]) {
        s_gameOver = true;
        s_deathStart = millis();
        s_animTimer = millis();
        s_deathAnimDone = false;
        snake_saveHighScore();
      }
    }

    if (s_snakeX[0] == s_foodX && s_snakeY[0] == s_foodY) {
      if (s_snakeLength < S_MAX_LENGTH) s_snakeLength++;
      s_score++;
      snake_placeFood();
      if (s_speed > 75) s_speed -= 2;
      snake_saveHighScore();
    }
  }

  // ========== رسم ==========
  display.clearDisplay();

  display.setTextSize(1);
  display.setCursor(0, 0);
  display.print("Score:");
  display.print(s_score);

  // R فقط یک بار
  if (s_showR) {
    if (millis() - s_rTimer < 900) {
      display.setCursor(118, 0);
      display.print("R");
    } else {
      s_showR = false;
    }
  }

  for (int i = 0; i < s_snakeLength; i++) {
    display.fillRect(s_snakeX[i], s_snakeY[i], S_GRID_SIZE, S_GRID_SIZE, SSD1306_WHITE);
  }

  display.fillCircle(s_foodX + 2, s_foodY + 2, 2, SSD1306_WHITE);

  display.display();
}
void pac_loop() {
  // ========== منوی اصلی ==========
  if (p_inMenu) {
    if (millis() - p_animTimer > 280) {
      p_animTimer = millis();
      p_animOffset += p_animDir ? 1 : -1;
      if (p_animOffset > 3) p_animDir = false;
      if (p_animOffset < -3) p_animDir = true;
    }
    if (digitalRead(BTN_UP) == LOW) { p_menuIndex = 0; delay(200); }
    if (digitalRead(BTN_DOWN) == LOW) { p_menuIndex = 1; delay(200); }
    if (digitalRead(BTN_OK) == LOW) {
      delay(250);
      if (p_menuIndex == 0) { p_inMenu = false; pac_resetGame(); }
      else { p_inMenu = false; p_inDiffMenu = true; }
    }

    display.clearDisplay();
    display.setTextSize(2);
    display.setTextColor(SSD1306_WHITE);
    display.setCursor(10 + p_animOffset, 8);
    display.print("KomiXer 2");

    display.setTextSize(1);
    display.setCursor(35, 32);
    if (p_menuIndex == 0) display.print("> Start");
    else display.print("  Start");
    display.setCursor(18, 48);
    if (p_menuIndex == 1) display.print("> Select Difficulty");
    else display.print("  Select Difficulty");
    display.display();
    return;
  }

  // ========== منوی سختی ==========
  if (p_inDiffMenu) {
    if (digitalRead(BTN_UP) == LOW) { if (p_diffIndex > 0) p_diffIndex--; delay(200); }
    if (digitalRead(BTN_DOWN) == LOW) { if (p_diffIndex < 2) p_diffIndex++; delay(200); }
    if (digitalRead(BTN_OK) == LOW) {
      delay(250);
      p_currentDiff = p_diffIndex;
      EEPROM.write(P_EEPROM_DIFF, p_currentDiff);
      EEPROM.commit();
      p_inDiffMenu = false;
      p_inMenu = true;
    }

    display.clearDisplay();
    display.setTextSize(1);
    display.setCursor(30, 6);
    display.print("Difficulty");
    display.setCursor(40, 24);
    if (p_diffIndex == 0) display.print("> Easy"); else display.print("  Easy");
    display.setCursor(35, 38);
    if (p_diffIndex == 1) display.print("> Normal"); else display.print("  Normal");
    display.setCursor(40, 52);
    if (p_diffIndex == 2) display.print("> Hard"); else display.print("  Hard");
    display.display();
    return;
  }

  // ========== Pause ==========
  if (!p_gameOver && digitalRead(BTN_OK) == LOW) {
    delay(180);
    if (p_isPaused) {
      p_isPaused = false;
      p_okPressCount = 0;
    } else {
      if (millis() - p_lastOkPress < 500) p_okPressCount++;
      else p_okPressCount = 1;
      p_lastOkPress = millis();
      if (p_okPressCount >= 2) { p_isPaused = true; p_okPressCount = 0; }
    }
  }

  if (p_isPaused && digitalRead(BTN_DOWN) == LOW) {
    delay(250);
    p_isPaused = false;
    p_inMenu = true;
  }

  if (p_isPaused) {
    display.clearDisplay();
    display.setTextSize(2);
    display.setCursor(28, 18);
    display.print("PAUSE!");
    display.setTextSize(1);
    display.setCursor(22, 48);
    display.print("DOWN = Menu");
    display.display();
    return;
  }

  // ========== Game Over ==========
  if (p_gameOver || p_win) {
    if (!p_deathAnimDone) {
      if (millis() - p_deathStart > 1800) p_deathAnimDone = true;
      if (millis() - p_animTimer > 350) {
        p_animTimer = millis();
        p_animOffset = (p_animOffset == 0) ? 1 : 0;
      }
      display.clearDisplay();
      if (p_animOffset == 0) {
        display.setTextSize(2);
        display.setCursor(12, 8);
        display.print(p_win ? "YOU WIN!" : "Game Over");
      }
      if (!p_win) pac_drawSkull(52, 30);
      display.display();
      return;
    }

    // صفحه نهایی
    if (millis() - p_animTimer > 350) {
      p_animTimer = millis();
      p_animOffset = (p_animOffset == 0) ? 2 : 0;
    }
    display.clearDisplay();
    display.setTextSize(2);
    display.setCursor(12 + p_animOffset, 10);
    display.print(p_win ? "YOU WIN!" : "Game Over");

    display.setTextSize(1);
    display.setCursor(30, 34);
    display.print("Score: ");
    display.print(p_score);

    display.setCursor(8, 48);
    if (p_currentDiff == 0) display.print("Easy Best: ");
    else if (p_currentDiff == 1) display.print("Normal Best: ");
    else display.print("Hard Best: ");
    display.print(pac_getCurrentHighScore());

    if (p_isNewRecord) pac_drawStar(110, 38);

    display.display();
    if (digitalRead(BTN_OK) == LOW) {
      delay(300);
      p_inMenu = true;
    }
    return;
  }

  // ========== کنترل ==========
  if (digitalRead(BTN_UP) == LOW && p_dir != 2) { p_dir = 0; delay(120); }
  if (digitalRead(BTN_DOWN) == LOW && p_dir != 0) { p_dir = 2; delay(120); }
  if (digitalRead(BTN_LEFT) == LOW && p_dir != 1) { p_dir = 3; delay(120); }
  if (digitalRead(BTN_RIGHT) == LOW && p_dir != 3) { p_dir = 1; delay(120); }

  // ========== حرکت پک‌من ==========
  if (millis() - p_lastMove > p_speed) {
    p_lastMove = millis();
    int nx = p_pacX, ny = p_pacY;
    if (p_dir == 0) ny--;
    if (p_dir == 1) nx++;
    if (p_dir == 2) ny++;
    if (p_dir == 3) nx--;

    if (pac_canMove(nx, ny)) {
      p_pacX = nx; p_pacY = ny;
      if (p_gameMap[p_pacY][p_pacX] == 2) {
        p_gameMap[p_pacY][p_pacX] = 0;
        p_score += 10;
        p_dotsLeft--;
        pac_saveHighScore();
        if (p_dotsLeft <= 0) {
          p_win = true;
          p_gameOver = true;
          p_deathStart = millis();
          p_animTimer = millis();
          p_deathAnimDone = false;
          pac_saveHighScore();
        }
      }
    }
  }

  // ========== حرکت روح ==========
  if (millis() - p_lastGhost > p_ghostSpeed) {
    p_lastGhost = millis();
    pac_moveGhost();
  }

  // برخورد با روح
  if (p_pacX == p_ghostX && p_pacY == p_ghostY) {
    p_gameOver = true;
    p_deathStart = millis();
    p_animTimer = millis();
    p_deathAnimDone = false;
    pac_saveHighScore();
  }

  // ========== رسم ==========
  display.clearDisplay();

  // امتیاز
  display.setTextSize(1);
  display.setCursor(0, 0);
  display.print("Score:");
  display.print(p_score);

  if (p_showR && millis() - p_rTimer < 900) {
    display.setCursor(118, 0);
    display.print("R");
  } else p_showR = false;

  // نقشه
  int offsetY = 8;
  for (int y = 0; y < P_MAP_H; y++) {
    for (int x = 0; x < P_MAP_W; x++) {
      int px = x * P_TILE;
      int py = y * P_TILE + offsetY;
      if (p_gameMap[y][x] == 1) {
        display.fillRect(px, py, P_TILE, P_TILE, SSD1306_WHITE);
      } else if (p_gameMap[y][x] == 2) {
        display.fillRect(px + 1, py + 1, 2, 2, SSD1306_WHITE); // نقطه
      }
    }
  }

  // پک‌من
  display.fillCircle(p_pacX * P_TILE + 2, p_pacY * P_TILE + offsetY + 2, 2, SSD1306_WHITE);

  // روح
  display.fillCircle(p_ghostX * P_TILE + 2, p_ghostY * P_TILE + offsetY + 2, 2, SSD1306_WHITE);
  display.drawPixel(p_ghostX * P_TILE + 1, p_ghostY * P_TILE + offsetY + 1, SSD1306_BLACK);
  display.drawPixel(p_ghostX * P_TILE + 3, p_ghostY * P_TILE + offsetY + 1, SSD1306_BLACK);

  display.display();
}
